-- Generated by Murakumo: load nyc_tlc.yellow_tripdata (append), without Murakumo. Run it from the project folder.

-- The files under landing/nyc_tlc/yellow_tripdata/ that were not loaded before.
create or replace temp table new_rows as
select cast("VendorID" as INTEGER) as "VendorID", cast(tpep_pickup_datetime as TIMESTAMP) as tpep_pickup_datetime, cast(tpep_dropoff_datetime as TIMESTAMP) as tpep_dropoff_datetime, cast(passenger_count as INTEGER) as passenger_count, cast(trip_distance as DECIMAL(10,2)) as trip_distance, cast("RatecodeID" as INTEGER) as "RatecodeID", cast(store_and_fwd_flag as VARCHAR) as store_and_fwd_flag, cast("PULocationID" as INTEGER) as "PULocationID", cast("DOLocationID" as INTEGER) as "DOLocationID", cast(payment_type as INTEGER) as payment_type, cast(fare_amount as DECIMAL(10,2)) as fare_amount, cast(extra as DECIMAL(10,2)) as extra, cast(mta_tax as DECIMAL(10,2)) as mta_tax, cast(tip_amount as DECIMAL(10,2)) as tip_amount, cast(tolls_amount as DECIMAL(10,2)) as tolls_amount, cast(improvement_surcharge as DECIMAL(10,2)) as improvement_surcharge, cast(total_amount as DECIMAL(10,2)) as total_amount, cast(congestion_surcharge as DECIMAL(10,2)) as congestion_surcharge, cast("Airport_fee" as DECIMAL(10,2)) as "Airport_fee", filename
from read_json('landing/nyc_tlc/yellow_tripdata/yellow_tripdata_*.jsonl', format = 'newline_delimited', filename = true, columns = {'VendorID': 'INTEGER', 'tpep_pickup_datetime': 'TIMESTAMP', 'tpep_dropoff_datetime': 'TIMESTAMP', 'passenger_count': 'INTEGER', 'trip_distance': 'DECIMAL(10,2)', 'RatecodeID': 'INTEGER', 'store_and_fwd_flag': 'VARCHAR', 'PULocationID': 'INTEGER', 'DOLocationID': 'INTEGER', 'payment_type': 'INTEGER', 'fare_amount': 'DECIMAL(10,2)', 'extra': 'DECIMAL(10,2)', 'mta_tax': 'DECIMAL(10,2)', 'tip_amount': 'DECIMAL(10,2)', 'tolls_amount': 'DECIMAL(10,2)', 'improvement_surcharge': 'DECIMAL(10,2)', 'total_amount': 'DECIMAL(10,2)', 'congestion_surcharge': 'DECIMAL(10,2)', 'Airport_fee': 'DECIMAL(10,2)'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'yellow_tripdata');
-- Append: the new files' rows are added.
insert into raw_nyc_tlc.yellow_tripdata ("VendorID", tpep_pickup_datetime, tpep_dropoff_datetime, passenger_count, trip_distance, "RatecodeID", store_and_fwd_flag, "PULocationID", "DOLocationID", payment_type, fare_amount, extra, mta_tax, tip_amount, tolls_amount, improvement_surcharge, total_amount, congestion_surcharge, "Airport_fee", _ingested_at, _batch_id)
select "VendorID", tpep_pickup_datetime, tpep_dropoff_datetime, passenger_count, trip_distance, "RatecodeID", store_and_fwd_flag, "PULocationID", "DOLocationID", payment_type, fare_amount, extra, mta_tax, tip_amount, tolls_amount, improvement_surcharge, total_amount, congestion_surcharge, "Airport_fee", now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'yellow_tripdata', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
